	private final Client client;
	private final AnchorApiClient api;
	private final ClientThread clientThread;
	private volatile IncrementalSync incrementalSync;

	@Inject
	public PlayerProgressService(Client client, AnchorApiClient api, ClientThread clientThread)
	{
		this.client = client;
		this.api = api;
		this.clientThread = clientThread;
	}

	/** Keeps the lightweight unit-test constructor while production uses ClientThread. */
	public PlayerProgressService(Client client, AnchorApiClient api)
	{
		this(client, api, null);
	}

	public void syncAll()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return;
		}

		if (clientThread == null)
		{
			send(collect());
			return;
		}
		if (incrementalSync != null) return;
		incrementalSync = new IncrementalSync();
		clientThread.invokeLater(this::advanceIncrementalSync);
	}

	private void advanceIncrementalSync()
	{
		IncrementalSync sync = incrementalSync;
		if (sync == null) return;
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			incrementalSync = null;
			return;
		}

		try
		{
			switch (sync.stage)
			{
				case 0:
					sync.request.syncId = UUID.randomUUID().toString();
					sync.request.capturedAt = Instant.now().toString();
					sync.request.player = new AnchorModels.PlayerIdentity();
					sync.request.player.name = client.getLocalPlayer().getName();
					sync.request.player.accountHash = Long.toString(client.getAccountHash());
					sync.request.combatAchievements = newCombatAchievementProgress();
					sync.request.quests = new AnchorModels.QuestProgress();
					sync.stage = 1;
					break;
				case 1:
					if (sync.questIndex < Quest.values().length)
					{
						appendQuest(sync.request.quests, Quest.values()[sync.questIndex++]);
						break;
					}
					sync.request.achievementDiaries = new AnchorModels.AchievementDiaryProgress();
					sync.stage = 2;
					break;
				case 2:
					if (sync.diaryArea < DIARY_AREAS.length)
					{
						AnchorModels.AchievementDiaryArea area = collectDiaryArea(sync.diaryArea++);
						sync.request.achievementDiaries.areas.add(area);
						for (AnchorModels.AchievementDiaryTier tier : area.tiers)
						{
							sync.request.achievementDiaries.completedTasks += tier.completedCount;
							sync.request.achievementDiaries.totalTasks += tier.totalCount;
						}
						break;
					}
					sync.stage = 3;
					break;
				case 3:
					if (advanceCombatAchievements(sync)) break;
					sync.stage = 4;
					break;
				case 4:
					sync.request.skills = collectSkills();
					sync.stage = 5;
					break;
				case 5:
					incrementalSync = null;
					send(sync.request);
					return;
				default:
					incrementalSync = null;
					return;
			}
		}
		catch (RuntimeException e)
		{
			incrementalSync = null;
			log.error("Unable to collect Anchor player progress", e);
			return;
		}

		clientThread.invokeLater(this::advanceIncrementalSync);
	}

	/** Processes at most one diary area or one combat-achievement task per client loop. */
	private boolean advanceCombatAchievements(IncrementalSync sync)
	{
		if (sync.tierIndex >= TIER_ENUMS.size())
		{
			finishCombatAchievementProgress(sync.request.combatAchievements);
			return false;
		}

		if (sync.structIds == null)
		{
			Map.Entry<Integer, String> tier = new java.util.ArrayList<>(TIER_ENUMS.entrySet()).get(sync.tierIndex);
			EnumComposition composition = client.getEnum(tier.getKey());
			sync.tierName = tier.getValue();
			sync.structIds = composition == null ? new int[0] : composition.getIntVals();
			if (sync.structIds == null) sync.structIds = new int[0];
		}
		if (sync.structIndex < sync.structIds.length)
		{
			AnchorModels.CombatTask task = loadTask(sync.structIds[sync.structIndex++], sync.tierName);
			if (task != null)
			{
				sync.request.combatAchievements.tasks.add(task);
				sync.request.combatAchievements.totalPossiblePoints += task.points;
				AnchorModels.TierProgress tier = sync.request.combatAchievements.tierProgress.get(task.tier.toLowerCase());
				tier.total++;
				if (task.completed) { sync.request.combatAchievements.completedTasks++; tier.obtained++; }
			}
			return true;
		}

		sync.tierIndex++;
		sync.structIds = null;
		sync.structIndex = 0;
		return true;
	}

	private void send(AnchorModels.PlayerProgressRequest request)
	{
		api.syncPlayerProgress(request, result ->
		{
			if (!result.isSuccessful())
			{
				log.error("Anchor progress sync failed: player={}, syncId={}, error={}",
					request.player.name, request.syncId, result.error);
			}
		});
	}

	private AnchorModels.CombatAchievementProgress newCombatAchievementProgress()
	{
		AnchorModels.CombatAchievementProgress result = new AnchorModels.CombatAchievementProgress();
		for (String tier : TIER_ENUMS.values())
			result.tierProgress.put(tier.toLowerCase(), new AnchorModels.TierProgress());
		return result;
	}

	private void finishCombatAchievementProgress(AnchorModels.CombatAchievementProgress result)
	{
		result.totalTasks = result.tasks.size();
		result.totalPoints = client.getVarbitValue(VarbitID.CA_POINTS);
		result.currentTier = currentTier(result.totalPoints);
		int identifiedCompleted = result.completedTasks;
		int authoritativeCompleted = 0;
		for (String tier : TIER_ENUMS.values())
		{
			int reported = Math.max(0, client.getVarbitValue(CA_COMPLETED_VARBITS.get(tier)));
			AnchorModels.TierProgress progress = result.tierProgress.get(tier.toLowerCase());
			progress.obtained = Math.min(reported, progress.total);
			authoritativeCompleted += progress.obtained;
		}
		result.completedTasks = authoritativeCompleted;
		if (identifiedCompleted != authoritativeCompleted)
		{
			log.error("Combat achievement bitmap coverage mismatch: identified={}, authoritative={}, highestSupportedTaskId={}",
				identifiedCompleted, authoritativeCompleted, COMPLETION_VARPS.length * 32 - 1);
		}
	}

	private AnchorModels.AchievementDiaryArea collectDiaryArea(int areaId)
	{
		AnchorModels.AchievementDiaryArea area = new AnchorModels.AchievementDiaryArea();
		area.id = areaId;
		area.name = DIARY_AREAS[areaId];
		for (int tierIndex = 0; tierIndex < DIARY_TIERS.length; tierIndex++)
		{
			AnchorModels.AchievementDiaryTier tier = new AnchorModels.AchievementDiaryTier();
			tier.name = DIARY_TIERS[tierIndex];
			tier.totalCount = DIARY_TOTALS[areaId][tierIndex];
			int completionValue = client.getVarbitValue(DIARY_COMPLETION_VARBITS[areaId][tierIndex]);
			int completed = client.getVarbitValue(DIARY_COUNT_VARBITS[areaId][tierIndex]);
			if (isDiaryComplete(areaId, tierIndex, completionValue)) completed = tier.totalCount;
			tier.completedCount = completed;
			tier.completedCount = Math.max(0, Math.min(tier.completedCount, tier.totalCount));
			tier.completed = tier.completedCount >= tier.totalCount;
			area.tiers.add(tier);
		}
		return area;
	}

	private static boolean isDiaryComplete(int areaId, int tierIndex, int value)
	{
		// Karamja's easy/medium/hard completion varbits use 2 as the completed value.
		return areaId == 0 && tierIndex < 3 ? value > 1 : value > 0;
	}

	private void appendQuest(AnchorModels.QuestProgress result, Quest quest)
	{
		String name = quest.getName();
		if (name == null || name.isBlank())
		{
			log.error("Skipping quest with missing name: enum={}, id={}", quest.name(), quest.getId());
			return;
		}
		AnchorModels.QuestSnapshot snapshot = new AnchorModels.QuestSnapshot();
		snapshot.id = quest.getId();
		snapshot.name = name.trim();
		QuestState state = quest.getState(client);
		snapshot.state = state == null ? QuestState.NOT_STARTED.name() : state.name();
		snapshot.completed = state == QuestState.FINISHED;
		result.quests.add(snapshot);
		result.totalCount++;
		if (snapshot.completed) result.completedCount++;
	}

	private final class IncrementalSync
	{
		private final AnchorModels.PlayerProgressRequest request = new AnchorModels.PlayerProgressRequest();
		private int stage;
		private int diaryArea;
		private int questIndex;
		private int tierIndex;
		private String tierName;
		private int[] structIds;
		private int structIndex;
	}

	AnchorModels.PlayerProgressRequest collect()
	{
		AnchorModels.PlayerProgressRequest request = new AnchorModels.PlayerProgressRequest();
		request.syncId = UUID.randomUUID().toString();
		request.capturedAt = Instant.now().toString();
		request.player = new AnchorModels.PlayerIdentity();
		request.player.name = client.getLocalPlayer().getName();
		request.player.accountHash = Long.toString(client.getAccountHash());
		request.combatAchievements = collectCombatAchievements();
		request.quests = collectQuests();
		request.achievementDiaries = collectAchievementDiaries();
		request.skills = collectSkills();
		return request;
	}

	private AnchorModels.QuestProgress collectQuests()
	{
		AnchorModels.QuestProgress result = new AnchorModels.QuestProgress();
		for (Quest quest : Quest.values())
		{
			String name = quest.getName();
			if (name == null || name.isBlank())
			{
				log.error("Skipping quest with missing name: enum={}, id={}", quest.name(), quest.getId());
				continue;
			}
			AnchorModels.QuestSnapshot snapshot = new AnchorModels.QuestSnapshot();
			snapshot.id = quest.getId();
			snapshot.name = name.trim();
			QuestState state = quest.getState(client);
			// A client that has not populated quest varbits yet can return null.
			snapshot.state = state == null ? QuestState.NOT_STARTED.name() : state.name();
			snapshot.completed = state == QuestState.FINISHED;
			result.quests.add(snapshot);
			result.totalCount++;
			if (snapshot.completed) result.completedCount++;
		}
		return result;
	}

	private AnchorModels.AchievementDiaryProgress collectAchievementDiaries()
	{
		AnchorModels.AchievementDiaryProgress result = new AnchorModels.AchievementDiaryProgress();
		for (int areaId = 0; areaId < DIARY_AREAS.length; areaId++)
		{
			AnchorModels.AchievementDiaryArea area = collectDiaryArea(areaId);
			for (AnchorModels.AchievementDiaryTier tier : area.tiers)
			{
				result.completedTasks += tier.completedCount;
				result.totalTasks += tier.totalCount;
			}
			result.areas.add(area);
		}
		return result;
	}

	private AnchorModels.CombatAchievementProgress collectCombatAchievements()
	{
		AnchorModels.CombatAchievementProgress result = new AnchorModels.CombatAchievementProgress();
		for (String tier : TIER_ENUMS.values())
		{
			result.tierProgress.put(tier.toLowerCase(), new AnchorModels.TierProgress());
		}

		for (Map.Entry<Integer, String> tierEntry : TIER_ENUMS.entrySet())
		{
			EnumComposition tierEnum = client.getEnum(tierEntry.getKey());
			if (tierEnum == null || tierEnum.getIntVals() == null)
			{
				continue;
			}
			for (int structId : tierEnum.getIntVals())
			{
				AnchorModels.CombatTask task = loadTask(structId, tierEntry.getValue());
				if (task == null)
				{
					continue;
				}
				result.tasks.add(task);
				result.totalPossiblePoints += task.points;
				AnchorModels.TierProgress tier = result.tierProgress.get(task.tier.toLowerCase());
				tier.total++;
				if (task.completed)
				{
					result.completedTasks++;
					tier.obtained++;
				}
			}
		}

		result.totalTasks = result.tasks.size();
		result.totalPoints = client.getVarbitValue(VarbitID.CA_POINTS);
		result.currentTier = currentTier(result.totalPoints);
		int bitmaskCompleted = result.completedTasks;
		int authoritativeCompleted = 0;
		for (String tier : TIER_ENUMS.values())
		{
			int reported = Math.max(0, client.getVarbitValue(CA_COMPLETED_VARBITS.get(tier)));
			AnchorModels.TierProgress progress = result.tierProgress.get(tier.toLowerCase());
			progress.obtained = Math.min(reported, progress.total);
			authoritativeCompleted += progress.obtained;
		}
		result.completedTasks = authoritativeCompleted;
		if (bitmaskCompleted != authoritativeCompleted)
		{
			log.error("Combat achievement bitmap coverage mismatch: identified={}, authoritative={}, highestSupportedTaskId={}",
				bitmaskCompleted, authoritativeCompleted, COMPLETION_VARPS.length * 32 - 1);
		}
		return result;
	}

	private AnchorModels.CombatTask loadTask(int structId, String tier)
	{
		StructComposition struct = client.getStructComposition(structId);
		if (struct == null) return null;
		String name = struct.getStringValue(FIELD_NAME);
		if (name == null || name.isBlank()) return null;
		AnchorModels.CombatTask task = new AnchorModels.CombatTask();
		task.id = struct.getIntValue(FIELD_TASK_ID);
		task.name = name.trim();
		task.tier = tier;
		task.points = pointsForTier(tier);
		task.completed = isTaskCompleted(task.id);
		return task;
	}

	private boolean isTaskCompleted(int taskId)
	{
		if (taskId < 0 || taskId >= COMPLETION_VARPS.length * 32) return false;
		int value = client.getVarpValue(COMPLETION_VARPS[taskId / 32]);
		return (value & (1 << (taskId % 32))) != 0;
	}

	private AnchorModels.SkillProgress collectSkills()
	{
		AnchorModels.SkillProgress result = new AnchorModels.SkillProgress();
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL) continue;
			AnchorModels.SkillSnapshot snapshot = new AnchorModels.SkillSnapshot();
			snapshot.name = skill.getName();
			snapshot.level = client.getRealSkillLevel(skill);
			snapshot.experience = client.getSkillExperience(skill);
			result.skills.add(snapshot);
			result.totalLevel += snapshot.level;
			result.totalExperience += snapshot.experience;
		}
		return result;
	}

	private String currentTier(int points)
	{
		String current = "None";
		int[] thresholdVarbits = {
			VarbitID.CA_THRESHOLD_EASY, VarbitID.CA_THRESHOLD_MEDIUM, VarbitID.CA_THRESHOLD_HARD,
			VarbitID.CA_THRESHOLD_ELITE, VarbitID.CA_THRESHOLD_MASTER, VarbitID.CA_THRESHOLD_GRANDMASTER
		};
		int index = 0;
		for (String tier : TIER_ENUMS.values())
		{
			int threshold = client.getVarbitValue(thresholdVarbits[index++]);
			if (threshold > 0 && points >= threshold) current = tier;
		}
		return current;
	}

	private static int pointsForTier(String tier)
	{
		switch (tier.toLowerCase())
		{
			case "easy": return 1;
			case "medium": return 2;
			case "hard": return 3;
			case "elite": return 4;
			case "master": return 5;
			case "grandmaster": return 6;
			default: return 0;
		}
	}
}

package com.theanchor.service;

import com.theanchor.AnchorConfig;
import com.theanchor.api.AnchorApiClient;
import com.theanchor.model.AnchorModels;
import java.awt.image.BufferedImage;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class AnchorDataService
{
	static final String ANCHOR_ORIGIN = AnchorApiClient.ANCHOR_ORIGIN;
	// Replace these with the public images shown when authentication is missing or invalid.
	static final String UNAUTHENTICATED_BOTW_IMAGE_URL = "";
	static final String UNAUTHENTICATED_SOTW_IMAGE_URL = "";

	public enum Connection { NOT_CONFIGURED, CHECKING, CONNECTED, INVALID, UNAVAILABLE }
	@Inject private AnchorApiClient api;
	@Inject private AnchorConfig config;
	@Inject private ImageCache images;
	@Inject private RulesService rules;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();
	private volatile AnchorModels.Profile profile;
	private volatile AnchorModels.CompetitionPanels competitionPanels;
	private volatile AnchorModels.PvmDiaryStatus pvmDiaryStatus;
	private volatile BufferedImage profileImage;
	private volatile BufferedImage botwImage;
	private volatile BufferedImage sotwImage;
	private volatile BufferedImage unauthenticatedBotwImage;
	private volatile BufferedImage unauthenticatedSotwImage;
	private volatile long botwImageCompetitionId = Long.MIN_VALUE;
	private volatile long sotwImageCompetitionId = Long.MIN_VALUE;
	private volatile Connection connection = Connection.NOT_CONFIGURED;
	private volatile String message = "Log in to load your Anchor profile";
	private volatile String requestedPlayerName;
	private volatile boolean currentPlayerClanMember;

	public void addListener(Runnable listener) { listeners.add(listener); }
	public void removeListener(Runnable listener) { listeners.remove(listener); }
	public AnchorModels.Profile profile() { return profile; }
	public AnchorModels.CompetitionPanels competitionPanels() { return competitionPanels; }
	public AnchorModels.PvmDiaryStatus pvmDiaryStatus() { return pvmDiaryStatus; }
	public BufferedImage profileImage() { return profileImage; }
	public BufferedImage botwImage() { return botwImage; }
	public BufferedImage sotwImage() { return sotwImage; }
	public BufferedImage unauthenticatedBotwImage() { return unauthenticatedBotwImage; }
	public BufferedImage unauthenticatedSotwImage() { return unauthenticatedSotwImage; }
	public Connection connection() { return connection; }
	public String message() { return message; }
	public boolean isCurrentPlayerClanMember() { return currentPlayerClanMember; }

	public void loggedOut()
	{
		requestedPlayerName = null;
		currentPlayerClanMember = false;
		profile = null;
		pvmDiaryStatus = null;
		profileImage = null;
		message = "Log in to load your Anchor profile";
		notifyListeners();
	}

	public void refresh(String playerName)
	{
		if (playerName == null || playerName.isBlank()) { loggedOut(); return; }
		String requestedName = playerName.trim();
		if (!samePlayer(requestedPlayerName, requestedName))
		{
			profile = null;
			profileImage = null;
			pvmDiaryStatus = null;
			currentPlayerClanMember = false;
		}
		requestedPlayerName = requestedName;
		message = "Loading " + playerName + "…"; notifyListeners();
		api.getProfile(playerName, result ->
		{
			// An account switch can complete before the previous profile request. Never
			// let that stale response activate the plugin for the newly logged-in RSN.
			if (!samePlayer(requestedPlayerName, requestedName)) return;
			if (result.isSuccessful() && result.value != null)
			{
				profile = result.value;
				// The profile endpoint is queried for requestedName and only returns a
				// member profile for rostered players. Do not make feature activation
				// depend on the optional/canonical member.name response field.
				currentPlayerClanMember = profile.member != null;
				message = currentPlayerClanMember ? "Profile loaded" : "Not found in The Anchor roster";
				if (currentPlayerClanMember)
				{
					loadPvmDiaryStatus(requestedName);
					String url = profileImageUrl(playerName);
					images.loadProfile(playerName, url, image ->
					{
						if (samePlayer(requestedPlayerName, requestedName)) profileImage = image;
						notifyListeners();
					});
				}
				else profile = null;
			}
			else
			{
				profile = null;
				currentPlayerClanMember = false;
				message = result.statusCode == 404 ? "Not found in The Anchor roster" : result.error;
			}
			notifyListeners();
		});
		api.getCompetitionPanels(panelResult ->
		{
			AnchorModels.CompetitionPanels panels = panelResult.isSuccessful() ? panelResult.value : null;
			api.getCompetitions(compResult ->
			{
				AnchorModels.CompetitionPanels resolved = panels;
				if (compResult.isSuccessful() && compResult.value != null)
				{
					if (resolved == null) resolved = new AnchorModels.CompetitionPanels();
					resolved.botw = resolvePanel(resolved.botw, compResult.value.botw, "BOTW");
					resolved.sotw = resolvePanel(resolved.sotw, compResult.value.sotw, "SOTW");
				}
				competitionPanels = resolved;
				loadCompetitionImages(resolved);
				notifyListeners();
			});
		});
		loadUnauthenticatedCompetitionImages();
		rules.refresh(this::notifyListeners);
	}

	private void loadUnauthenticatedCompetitionImages()
	{
		if (!UNAUTHENTICATED_BOTW_IMAGE_URL.isBlank())
		{
			images.loadWebsiteImage("unauthenticated-botw", UNAUTHENTICATED_BOTW_IMAGE_URL,
				image -> { unauthenticatedBotwImage = image; notifyListeners(); });
		}
		if (!UNAUTHENTICATED_SOTW_IMAGE_URL.isBlank())
		{
			images.loadWebsiteImage("unauthenticated-sotw", UNAUTHENTICATED_SOTW_IMAGE_URL,
				image -> { unauthenticatedSotwImage = image; notifyListeners(); });
		}
	}

	private static AnchorModels.CompetitionPanel resolvePanel(AnchorModels.CompetitionPanel panel,
		AnchorModels.CompetitionPair pair, String kind)
	{
		AnchorModels.Competition selected = selectCompetition(pair);
		if (selected == null) return panel;
		if (panel != null && panel.competitionId == selected.id)
		{
			return panel;
		}
		return CompetitionService.convertToPanel(selected, kind);
	}

	static AnchorModels.Competition selectCompetition(AnchorModels.CompetitionPair pair)
	{
		if (pair == null) return null;
		if (pair.current != null) return pair.current;
		if (pair.upcoming != null) return pair.upcoming;
		return pair.previous;
	}

	private void loadCompetitionImages(AnchorModels.CompetitionPanels panels)
	{
		loadCompetitionImage("botw", panels == null ? null : panels.botw);
		loadCompetitionImage("sotw", panels == null ? null : panels.sotw);
	}

	private void loadPvmDiaryStatus(String playerName)
	{
		if (playerName == null || playerName.isBlank()) { pvmDiaryStatus = null; return; }
		api.getPvmDiaryStatus(playerName, result ->
		{
			if (!samePlayer(requestedPlayerName, playerName)) return;
			pvmDiaryStatus = result.isSuccessful() ? result.value : null;
			notifyListeners();
		});
	}

	static boolean samePlayer(String first, String second)
	{
		return normalizePlayerName(first).equals(normalizePlayerName(second));
	}

	private static String normalizePlayerName(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(java.util.Locale.ROOT)
			.replace(" ", "").replace("_", "").replace("-", "");
	}

	private void loadCompetitionImage(String kind, AnchorModels.CompetitionPanel panel)
	{
		long competitionId = panel == null ? 0 : panel.competitionId;
		if ("botw".equals(kind))
		{
			if (botwImageCompetitionId != competitionId) botwImage = null;
			botwImageCompetitionId = competitionId;
		}
		else
		{
			if (sotwImageCompetitionId != competitionId) sotwImage = null;
			sotwImageCompetitionId = competitionId;
		}
		String url = ANCHOR_ORIGIN + "/" + kind + ".png";
		if (competitionId <= 0) { images.loadWebsiteImage(kind, url, image -> setCompetitionImage(kind, competitionId, image)); return; }
		String key = kind + "-" + competitionId;
		images.loadWebsiteImage(key, url, image -> setCompetitionImage(kind, competitionId, image));
	}

	private void setCompetitionImage(String kind, long competitionId, BufferedImage image)
	{
		if ("botw".equals(kind))
		{
			if (botwImageCompetitionId == competitionId) botwImage = image;
		}
		else if (sotwImageCompetitionId == competitionId) sotwImage = image;
		notifyListeners();
	}

	static String profileImageUrl(String playerName)
	{
		return ANCHOR_ORIGIN + "/api/profile-portrait?name="
			+ URLEncoder.encode(playerName == null ? "" : playerName, StandardCharsets.UTF_8).replace("+", "%20");
	}

	public void validate()
	{
		String code = config.authenticationCode() == null ? "" : config.authenticationCode().trim();
		if (code.isEmpty()) { connection = Connection.NOT_CONFIGURED; notifyListeners(); return; }
		connection = Connection.CHECKING; notifyListeners();
		api.validateSession(result ->
		{
			connection = result.isSuccessful() ? Connection.CONNECTED
				: result.statusCode == 401 || result.statusCode == 403 ? Connection.INVALID : Connection.UNAVAILABLE;
			notifyListeners();
		});
	}

	private void notifyListeners() { for (Runnable listener : listeners) listener.run(); }
}

package com.theanchor.service;


import com.theanchor.AnchorConfig;
import com.theanchor.api.AnchorApiClient;
import com.theanchor.model.AnchorModels;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class BingoService
{
	private final AnchorApiClient api;
	private final AnchorDataService data;
	@Inject private AnchorConfig config;
	private volatile AnchorModels.BingoEvent event;
	private volatile AnchorModels.BingoRules rules;
	private volatile Set<Integer> itemIds = java.util.Collections.emptySet();
	private volatile Set<Integer> bossIds = java.util.Collections.emptySet();
	private volatile long lastBossSourceAt;

	@Inject
	public BingoService(AnchorApiClient api, AnchorDataService data)
	{
		this.api = api;
		this.data = data;
	}

	public AnchorModels.BingoEvent current() { return event; }
	public AnchorModels.BingoRules currentRules() { return rules; }
	public AnchorModels.BingoTeam currentTeam()
	{
		AnchorModels.BingoEvent active = event;
		AnchorModels.Profile profile = data.profile();
		if (active == null || active.teamsByDiscordId == null || profile == null || profile.member == null
			|| profile.member.discordId == null) return null;
		return active.teamsByDiscordId.get(profile.member.discordId.trim());
	}

	public void refresh()
	{
		api.getBingo(result ->
		{
			if (!result.isSuccessful())
			{
				if (result.statusCode == 401 || result.statusCode == 403) clear();
				return;
			}
			if (result.value == null || !result.value.active)
			{
				clear();
				return;
			}
			event = result.value;
		});
		api.getBingoRules(result ->
		{
			if (!result.isSuccessful())
			{
				if (result.statusCode == 401 || result.statusCode == 403) clearRules();
				return;
			}
			if (result.value == null) { clearRules(); return; }
			itemIds = immutableSet(result.value.itemIds);
			bossIds = immutableSet(result.value.bossIds);
			rules = result.value;
		});
	}

	public void clear()
	{
		event = null;
		clearRules();
	}

	private void clearRules()
	{
		rules = null;
		itemIds = java.util.Collections.emptySet();
		bossIds = java.util.Collections.emptySet();
		lastBossSourceAt = 0;
	}

	public List<AnchorModels.Item> matchingItems(Integer bossId, List<AnchorModels.Item> items)
	{
		return matchingItems(bossId, null, items);
	}

	public List<AnchorModels.Item> matchingItems(Integer bossId, String sourceName, List<AnchorModels.Item> items)
	{
		AnchorModels.BingoRules activeRules = rules;
		if (event == null || activeRules == null || activeRules.triggers == null || items == null)
			return java.util.Collections.emptyList();
		Set<AnchorModels.Item> matches = new LinkedHashSet<>();
		for (AnchorModels.Item item : items)
			if (item != null && activeRules.triggers.matchingItem && itemIds.contains(item.itemId)) matches.add(item);
		if (activeRules.triggers.ordinaryBossLoot && isBossSource(bossId, sourceName)) matches.addAll(items);
		return new ArrayList<>(matches);
	}

	public boolean shouldCaptureCollectionLog(List<AnchorModels.Item> items)
	{
		AnchorModels.BingoRules activeRules = rules;
		if (event == null || activeRules == null || activeRules.triggers == null
			|| !activeRules.triggers.bossCollectionLog || items == null) return false;
		if (hasRecentBossSource()) return true;
		for (AnchorModels.Item item : items) if (item != null && itemIds.contains(item.itemId)) return true;
		return false;
	}

	public boolean shouldCapturePet(Integer bossId, String sourceName, List<Integer> petItemIds)
	{
		AnchorModels.BingoRules activeRules = rules;
		if (event == null || activeRules == null || activeRules.triggers == null
			|| !activeRules.triggers.bossPet) return false;
		if (isBossSource(bossId, sourceName)) return true;
		if (hasRecentBossSource()) return true;
		if (petItemIds != null) for (Integer itemId : petItemIds) if (itemId != null && itemIds.contains(itemId)) return true;
		return false;
	}

	public boolean isBossSource(Integer bossId, String sourceName)
	{
		if (bossId != null && bossIds.contains(bossId)) return true;
		// Raid reward chests are emitted by RuneLite as named loot events without an NPC ID.
		return BossRegistry.isRaid(sourceName);
	}

	public void observeSource(Integer bossId, String sourceName)
	{
		if (isBossSource(bossId, sourceName)) lastBossSourceAt = System.currentTimeMillis();
	}

	private boolean hasRecentBossSource()
	{
		return lastBossSourceAt > 0 && System.currentTimeMillis() - lastBossSourceAt <= 10_000L;
	}

	public String eventType()
	{
		String type = rules == null || rules.evidence == null ? null : rules.evidence.eventType;
		return type == null || type.isBlank() ? "bingo" : type.trim();
	}

	public boolean screenshotRequired()
	{
		return rules == null || rules.evidence == null || rules.evidence.screenshotRequired;
	}

	public boolean finalizeSubmission()
	{
		return (config == null || config.autoSubmitEnabled())
			&& (rules == null || rules.evidence == null || rules.evidence.finalizeSubmission);
	}

	public String rulesVersion() { return rules == null ? null : rules.rulesVersion; }

	public void decorateDetails(Map<String, Object> details)
	{
		if (details == null) return;
		AnchorModels.BingoEvent active = event;
		if (active != null && active.eventTitle != null) details.put("eventTitle", active.eventTitle);
		if (rulesVersion() != null) details.put("bingoRulesVersion", rulesVersion());
		AnchorModels.BingoTeam team = currentTeam();
		if (team != null)
		{
			if (team.teamId != null) details.put("teamId", team.teamId);
			if (team.teamName != null) details.put("teamName", team.teamName);
		}
	}

	private static Set<Integer> immutableSet(List<Integer> values)
	{
		if (values == null || values.isEmpty()) return java.util.Collections.emptySet();
		return java.util.Collections.unmodifiableSet(new HashSet<>(values));
	}
}

